namespace MyApp.Services;

/// <summary>
/// Higher-level file system operations with built-in safety checks.
/// </summary>
public interface IFileSystemWrapper
{
    string ReadAllText(string path);
    byte[] ReadAllBytes(string path);
    string[] ReadAllLines(string path);

    void WriteAllText(string path, string contents);
    void WriteAllBytes(string path, byte[] bytes);
    void WriteAllLines(string path, string[] lines);

    /// <summary>Writes to a temp file then moves it into place to avoid partial writes.</summary>
    void SafeWriteAllText(string path, string contents);

    bool FileExists(string path);
    bool DirectoryExists(string path);

    void EnsureDirectoryExists(string path);
    void DeleteFileIfExists(string path);
    void DeleteDirectoryIfExists(string path, bool recursive);

    void CopyFile(string source, string destination, bool overwrite = false);
    void MoveFile(string source, string destination, bool overwrite = false);

    string[] GetFiles(string path, string searchPattern = "*", SearchOption searchOption = SearchOption.TopDirectoryOnly);
    string[] GetDirectories(string path, string searchPattern = "*", SearchOption searchOption = SearchOption.TopDirectoryOnly);

    Stream OpenRead(string path);
    Stream OpenWrite(string path);
}

using System.IO.Abstractions;

namespace MyApp.Services;

/// <summary>
/// Wraps <see cref="IFileSystem"/> with higher-level operations,
/// automatic directory creation, and atomic write support.
/// </summary>
public class FileSystemWrapper(IFileSystem fileSystem) : IFileSystemWrapper
{
    public string ReadAllText(string path) =>
        fileSystem.File.ReadAllText(path);

    public byte[] ReadAllBytes(string path) =>
        fileSystem.File.ReadAllBytes(path);

    public string[] ReadAllLines(string path) =>
        fileSystem.File.ReadAllLines(path);

    public void WriteAllText(string path, string contents)
    {
        EnsureParentDirectoryExists(path);
        fileSystem.File.WriteAllText(path, contents);
    }

    public void WriteAllBytes(string path, byte[] bytes)
    {
        EnsureParentDirectoryExists(path);
        fileSystem.File.WriteAllBytes(path, bytes);
    }

    public void WriteAllLines(string path, string[] lines)
    {
        EnsureParentDirectoryExists(path);
        fileSystem.File.WriteAllLines(path, lines);
    }

    public void SafeWriteAllText(string path, string contents)
    {
        EnsureParentDirectoryExists(path);

        var dir = fileSystem.Path.GetDirectoryName(path)!;
        var tempPath = fileSystem.Path.Combine(dir, $".tmp_{fileSystem.Path.GetRandomFileName()}");

        try
        {
            fileSystem.File.WriteAllText(tempPath, contents);
            fileSystem.File.Move(tempPath, path, overwrite: true);
        }
        catch
        {
            // Clean up the temp file on failure.
            if (fileSystem.File.Exists(tempPath))
                fileSystem.File.Delete(tempPath);

            throw;
        }
    }

    public bool FileExists(string path) =>
        fileSystem.File.Exists(path);

    public bool DirectoryExists(string path) =>
        fileSystem.Directory.Exists(path);

    public void EnsureDirectoryExists(string path)
    {
        if (!fileSystem.Directory.Exists(path))
            fileSystem.Directory.CreateDirectory(path);
    }

    public void DeleteFileIfExists(string path)
    {
        if (fileSystem.File.Exists(path))
            fileSystem.File.Delete(path);
    }

    public void DeleteDirectoryIfExists(string path, bool recursive)
    {
        if (fileSystem.Directory.Exists(path))
            fileSystem.Directory.Delete(path, recursive);
    }

    public void CopyFile(string source, string destination, bool overwrite = false)
    {
        EnsureParentDirectoryExists(destination);
        fileSystem.File.Copy(source, destination, overwrite);
    }

    public void MoveFile(string source, string destination, bool overwrite = false)
    {
        EnsureParentDirectoryExists(destination);
        fileSystem.File.Move(source, destination, overwrite);
    }

    public string[] GetFiles(string path, string searchPattern = "*",
        SearchOption searchOption = SearchOption.TopDirectoryOnly) =>
        fileSystem.Directory.GetFiles(path, searchPattern, searchOption);

    public string[] GetDirectories(string path, string searchPattern = "*",
        SearchOption searchOption = SearchOption.TopDirectoryOnly) =>
        fileSystem.Directory.GetDirectories(path, searchPattern, searchOption);

    public Stream OpenRead(string path) =>
        fileSystem.File.OpenRead(path);

    public Stream OpenWrite(string path)
    {
        EnsureParentDirectoryExists(path);
        return fileSystem.FileStream.New(path, FileMode.Create, FileAccess.Write);
    }

    private void EnsureParentDirectoryExists(string filePath)
    {
        var dir = fileSystem.Path.GetDirectoryName(filePath);
        if (dir is not null && !fileSystem.Directory.Exists(dir))
            fileSystem.Directory.CreateDirectory(dir);
    }
}

